<script setup lang="ts">const{preferences,loadPreferences,savePreferences}=useNotifications();const saved=ref(false);onMounted(loadPreferences);async function save(){await savePreferences();saved.value=true;setTimeout(()=>saved.value=false,1800);}</script>
<template><AccountShell title="تنظیمات اعلان‌ها" description="کانال، موضوع و ساعات دریافت پیام را مدیریت کنید"><form class="notification-settings" @submit.prevent="save"><fieldset><legend>کانال‌ها</legend><label><input v-model="preferences.in_app_enabled" type="checkbox">اعلان داخل هفت‌سو</label><label><input v-model="preferences.sms_enabled" type="checkbox">پیامک</label><label><input v-model="preferences.email_enabled" type="checkbox">ایمیل</label><label><input v-model="preferences.push_enabled" type="checkbox">Push</label></fieldset><fieldset><legend>ساعات سکوت</legend><div class="form-row"><label>از<input v-model="preferences.quiet_start" type="time"></label><label>تا<input v-model="preferences.quiet_end" type="time"></label></div><small>هشدار امنیتی داخل برنامه همیشه فعال می‌ماند.</small></fieldset><button class="button button-primary" type="submit">ذخیره تنظیمات</button><span v-if="saved" role="status">ذخیره شد.</span></form></AccountShell></template>
